                $display("Error: Ones digit mismatch at time %0t. Expected %b, got %b", $time, (q[3:0] + 1) % 10, q[3:0]);
                errors = errors + 1;
            end

            // Check enable signals
            if (q[3:0] == 4'd0 && ena[0] !== 0) begin
                $display("Error: Enable for tens digit should be 0 at time %0t", $time);
                errors = errors + 1;
            end
            if (q[3:0] == 4'd9 && ena[0] !== 1) begin
                $display("Error: Enable for tens digit should be 1 at time %0t", $time);
                errors = errors + 1;
            end

