            if (ena[0] && q[7:4] !== (q[7:4] + 1) % 10) begin
                $display("Error: Tens digit mismatch at time %0t. Expected %b, got %b", $time, (q[7:4] + 1) % 10, q[7:4]);
                errors = errors + 1;
            end

            // Check for hundreds digit
            if (ena[1] && q[11:8] !== (q[11:8] + 1) % 10) begin
                $display("Error: Hundreds digit mismatch at time %0t. Expected %b, got %b", $time, (q[11:8] + 1) % 10, q[11:8]);
                errors = errors + 1;
            end

            // Check for thousands digit
            if (ena[2] && q[15:12] !== (q[15:12] + 1) % 10) begin
                $display("Error: Thousands digit mismatch at time %0t. Expected %b, got %b", $time, (q[15:12] + 1) % 10, q[15:12]);
                errors = errors + 1;
            end
        end

        // Final check
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
